// MB-SERVER-001 / MB-SERVER-002: maintained compatibility tests for the
// vendored 26.2 stack and the accepted 26.1.2 stack. They compare the INSTALLED
// codec/registries with independent digests of Mojang's official data-generator
// reports (tests/fixtures/official-reports-*.json, regenerated by
// scripts/verify-version-data.ts from the SHA-1-pinned jars), decode official
// numeric attribute ids through the production decoder, mineflayer's attribute
// handler and prismarine-physics, and check the vendored provenance chain.
import { strict as assert } from 'node:assert';
import { createHash } from 'node:crypto';
import { EventEmitter } from 'node:events';
import { readFileSync } from 'node:fs';
import { createRequire } from 'node:module';
import { join } from 'node:path';
import { describe, it } from 'node:test';
import { PROJECT_ROOT } from '../src/app/fixture-layout.ts';
import { LOCAL_COMPAT_PROFILE, checkVersionSupport, localCompatProblem, supportLevel, upstreamTestedVersions } from '../src/config/versions.ts';
import { mechanicsDatasetFor, mechanicsVerifiedFor, VersionKnowledge } from '../src/knowledge/knowledge.ts';
import { REVIEWED_NEW_PACKETS, compareDigest, orderFinding, packetCorrespondence, type ReportDigest } from '../scripts/lib/official-reports.ts';

const require = createRequire(import.meta.url);
type Any = any; // eslint-disable-line @typescript-eslint/no-explicit-any

const digest = (v: string): ReportDigest => JSON.parse(readFileSync(join(PROJECT_ROOT, 'tests', 'fixtures', `official-reports-${v}.json`), 'utf8')) as ReportDigest;
const gitBlob = (buf: Buffer) => createHash('sha1').update(`blob ${buf.length}\0`).update(buf).digest('hex');
const sha512 = (buf: Buffer) => `sha512-${createHash('sha512').update(buf).digest('base64')}`;

describe('installed codec and registries match the official reports', () => {
  const reference = digest('26.1.2');
  const correspondence = packetCorrespondence(reference, '26.1.2');
  for (const [version, sha1] of [
    ['26.1.2', '97ccd4c0ed3f81bbb7bfacddd1090b0c56f9bc51'],
    ['26.2', '823e2250d24b3ddac457a60c92a6a941943fcd6a'],
  ] as const) {
    it(`${version}: every block state, registry id order and packet id (official jar ${sha1.slice(0, 8)})`, () => {
      const d = digest(version);
      assert.equal(d.provenance.minecraftVersion, version);
      assert.equal(d.provenance.serverJarSha1, sha1);
      const findings = compareDigest(d, version, { correspondence, newPackets: REVIEWED_NEW_PACKETS[version] ?? {} });
      const failed = findings.filter((f) => !f.ok);
      assert.deepEqual(failed, [], failed.map((f) => `${f.area}: ${f.detail}`).join('\n'));
      // The attribute key mapper is checked at every numeric id (MB-SERVER-002).
      assert.ok(findings.some((f) => f.area.startsWith('codec.entity_update_attributes.key') && f.ok));
      assert.ok(findings.some((f) => f.area === 'blocks.stateDecode' && f.ok));
    });
  }

  it('a shifted or wrong identity fails even when every label has a reviewed alias', () => {
    const official = ['air_drag_modifier', 'armor', 'movement_speed'];
    const aliases = { armor: 'generic.armor', movement_speed: 'generic.movement_speed' };
    assert.equal(orderFinding('ok', official, ['air_drag_modifier', 'generic.armor', 'generic.movement_speed'], aliases).ok, true);
    // the stale pre-fix layout: names shifted by one id
    assert.equal(orderFinding('shifted', official, ['generic.armor', 'generic.movement_speed'], aliases).ok, false);
    // an unreviewed label difference at the right id is NOT accepted
    assert.equal(orderFinding('unreviewed', official, ['air_drag', 'generic.armor', 'generic.movement_speed'], aliases).ok, false);
  });
});

describe('MB-SERVER-002: server movement speed reaches physics', () => {
  const { Physics, PlayerState } = require('prismarine-physics') as Any;
  const { Vec3 } = require('vec3') as Any;
  const minecraftProtocol = require('minecraft-protocol') as Any;
  const varint = (n: number): Buffer => {
    const out: number[] = [];
    do {
      let b = n & 0x7f;
      n >>>= 7;
      if (n) b |= 0x80;
      out.push(b);
    } while (n);
    return Buffer.from(out);
  };

  for (const version of ['26.1.2', '26.2'] as const) {
    it(`${version}: official movement_speed id decodes, is stored under the physics key, and changes simulated speed`, () => {
      const d = digest(version);
      const attrId = d.registries['attribute']?.indexOf('movement_speed') ?? -1;
      const packetId = d.packets['play']?.['clientbound']?.indexOf('update_attributes') ?? -1;
      assert.equal(attrId, version === '26.2' ? 26 : 22);
      const value = Buffer.alloc(8);
      value.writeDoubleBE(0.0375);
      const raw = Buffer.concat([varint(packetId), varint(7), varint(1), varint(attrId), value, varint(0)]);
      const parsed = minecraftProtocol.createDeserializer({ state: 'play', isServer: false, version, noErrorLogging: true }).parsePacketBuffer(raw);
      assert.equal(parsed.metadata.size, raw.length);
      assert.equal(parsed.data.name, 'entity_update_attributes');
      assert.deepEqual(parsed.data.params.properties, [{ key: 'generic.movement_speed', value: 0.0375, modifiers: [] }]);
      // The same packet written by the production serializer uses the official id.
      const written = minecraftProtocol.createSerializer({ state: 'play', isServer: true, version }).createPacketBuffer({ name: 'entity_update_attributes', params: parsed.data.params });
      assert.deepEqual(written, raw);

      // Production mineflayer attribute handler (vendored entities.js).
      const registry = require('prismarine-registry')(version);
      const bot: Any = new EventEmitter();
      bot._client = new EventEmitter();
      bot.registry = registry;
      bot.version = version;
      bot.supportFeature = registry.supportFeature;
      require('mineflayer/lib/plugins/entities.js')(bot, {});
      bot._client.emit('entity_update_attributes', parsed.data.params);
      const entity = bot.entities[7];
      const physics = Physics(registry, { getBlock: () => null });
      assert.equal(physics.movementSpeedAttribute, 'minecraft:movement_speed');
      assert.equal(entity.attributes['minecraft:movement_speed'].value, 0.0375);
      assert.equal(entity.attributes['minecraft:movement_speed'], entity.attributes['generic.movement_speed'], 'one shared object, legacy label kept');

      // prismarine-physics: one tick walking forward on stone, server value vs default 0.1.
      const Block = require('prismarine-block')(registry);
      const stone = registry.blocksByName.stone.defaultState;
      const world = {
        getBlock: (pos: Any) => {
          const b = Block.fromStateId(pos.y < 0 ? stone : registry.blocksByName.air.defaultState, 0);
          b.position = pos.floored();
          return b;
        },
      };
      const step = (attributes: Any): number => {
        const fake: Any = {
          version,
          entity: { position: new Vec3(0.5, 0, 0.5), velocity: new Vec3(0, 0, 0), onGround: true, yaw: 0, pitch: 0, attributes, effects: {} },
          jumpTicks: 0,
          jumpQueued: false,
          inventory: { slots: [] },
        };
        const state = new PlayerState(fake, { forward: true, back: false, left: false, right: false, jump: false, sprint: false, sneak: false });
        Physics(registry, world).simulatePlayer(state, world);
        return Math.hypot(state.vel.x, state.vel.z);
      };
      const withServer = step(entity.attributes);
      const withDefault = step({});
      assert.ok(withDefault > 0);
      assert.ok(Math.abs(withServer / withDefault - 0.375) < 1e-9, `simulated speed ratio ${withServer / withDefault}`);
    });
  }
});

describe('version support levels', () => {
  it('26.1.x is upstream-tested; exactly 26.2 is the local compatibility profile; nothing else is admitted', () => {
    assert.equal(supportLevel('26.1.2'), 'upstream-tested');
    assert.equal(supportLevel('26.1'), 'upstream-tested');
    assert.equal(localCompatProblem(), undefined);
    assert.equal(supportLevel('26.2'), 'local-compat');
    assert.equal(checkVersionSupport('26.2'), undefined);
    assert.ok(!upstreamTestedVersions().includes('26.2'), 'the local admission is never reported as Mineflayer testing');
    assert.match(checkVersionSupport('26.3') ?? '', /not .*tested|no data/);
    assert.match(checkVersionSupport('26.2.1') ?? '', /no data/);
  });

  it('mechanics are dispatched by exact version and never borrowed', () => {
    assert.equal(mechanicsDatasetFor('26.1.2')?.provenance.serverJarSha1, '97ccd4c0ed3f81bbb7bfacddd1090b0c56f9bc51');
    assert.equal(mechanicsDatasetFor('26.2')?.provenance.serverJarSha1, '823e2250d24b3ddac457a60c92a6a941943fcd6a');
    assert.equal(mechanicsVerifiedFor('26.1.1'), false);
    assert.equal(mechanicsVerifiedFor('26.3'), false);
    const k = new VersionKnowledge({ version: '26.2' });
    const sulfur = k.answerOne({ kind: 'recipe', output: 'minecraft:sulfur_bricks' } as Any) as Any;
    assert.equal(sulfur.status, 'known', JSON.stringify(sulfur).slice(0, 300));
    const old = new VersionKnowledge({ version: '26.1.2' }).answerOne({ kind: 'recipe', output: 'minecraft:sulfur_bricks' } as Any) as Any;
    assert.notEqual(old.status, 'known', '26.1.2 has no sulfur blocks');
  });
});

describe('vendored provenance chain', () => {
  const lock = JSON.parse(readFileSync(join(PROJECT_ROOT, 'vendor', 'compat-lock.json'), 'utf8')) as { packages: Array<{ name: string; version: string; file: string; integrity: string; changedFiles: Record<string, string> }> };
  const sources = JSON.parse(readFileSync(join(PROJECT_ROOT, 'vendor', 'compat-sources.json'), 'utf8')) as { packages: Array<{ name: string; patches?: Array<{ file: string; fileBlobs: Record<string, { after: string }> }> }> };
  const packageLock = JSON.parse(readFileSync(join(PROJECT_ROOT, 'package-lock.json'), 'utf8')) as { packages: Record<string, { version: string; resolved: string; integrity: string }> };

  it('vendor tarballs, compat-lock, package-lock and the installed packages are the same bytes', () => {
    assert.deepEqual(lock.packages.map((p) => p.name).sort(), Object.keys(LOCAL_COMPAT_PROFILE.packages).sort());
    for (const entry of lock.packages) {
      assert.equal(sha512(readFileSync(join(PROJECT_ROOT, entry.file))), entry.integrity, entry.file);
      const locked = packageLock.packages[`node_modules/${entry.name}`];
      assert.equal(locked?.resolved, `file:${entry.file}`);
      assert.equal(locked?.integrity, entry.integrity);
      assert.equal(locked?.version, entry.version);
      const dir = join(PROJECT_ROOT, 'node_modules', entry.name);
      for (const [file, hash] of Object.entries(entry.changedFiles)) {
        assert.equal(createHash('sha256').update(readFileSync(join(dir, file))).digest('hex'), hash, `${entry.name}/${file}`);
      }
    }
  });

  it('every recorded patch result is what is installed', () => {
    for (const pkg of sources.packages) {
      for (const patch of pkg.patches ?? []) {
        for (const [file, blobs] of Object.entries(patch.fileBlobs)) {
          assert.equal(gitBlob(readFileSync(join(PROJECT_ROOT, 'node_modules', pkg.name, file))), blobs.after, `${pkg.name}/${file} (${patch.file})`);
        }
      }
    }
  });
});
